async function setup() {
  // PINSEL0: P0.4=TXD1, P0.5=RXD1 (func=01)
  _regW(0xE002C000, _regR(0xE002C000) | (0x01 << 8) | (0x01 << 10));
  // UART1: 9600 baud (PCLK=15MHz, divider=975)
  _regW(0xE0010008, 0x83); // Enable DLAB
  _regW(0xE0010000, 0x87); // DLL = 0x87
  _regW(0xE0010004, 0x03); // DLM = 0x03
  _regW(0xE0010008, 0x03); // 8N1, disable DLAB
}

async function loop() {
  var lsr = _regR(0xE0010014);
  if (lsr & 1) {
    var ch = _regR(0xE0010000);
    _regW(0xE0010000, ch);
  }
  await delay_ms(10);
}
